import type { TemplateView } from './TemplateView';

export interface IStatus {
    data?: any;
    setContext(context: TemplateView): unknown;
    onEnter(data?: any): void;
    onExit(data?: any): void;
    autoSpinUpdate?(): void;
    turboUpdate?(): void;
    spinUpdate?(): void;
}

export default class StatusManager {
    private spinCurrentState: IStatus
    private turboCurrentState: IStatus
    private autoCurrentState: IStatus

    public spinStatusChange(newStatus: IStatus) {
        if (this.spinCurrentState) this.spinCurrentState.onExit();
        this.spinCurrentState = newStatus;
        this.spinCurrentState.onEnter(this.spinCurrentState.data);
    }

    public turboStatusChange(newStatus: IStatus) {
        if (this.turboCurrentState) this.turboCurrentState.onExit();
        this.turboCurrentState = newStatus;
        this.turboCurrentState.onEnter();
    }

    public autoSpinStatusChange(newStatus: IStatus) {
        if (this.autoCurrentState) this.autoCurrentState.onExit();
        this.autoCurrentState = newStatus;
        this.autoCurrentState.onEnter();
    }

    autoSpinUpdate() {
        this.autoCurrentState.autoSpinUpdate();
    }
}
