import { _decorator, Button, Component, Label, Node } from 'cc';
const { ccclass, property } = _decorator;

@ccclass('1001/PopupProperty')
export class PopupProperty extends Component {
    @property(Node)
    public closeNode: Node = null!;
    @property({ type: Node, tooltip: '選配：左上角返回鈕，沒有就留空' })
    public backNode: Node | null = null;
    @property({ type: Node, tooltip: '選配：背景遮罩，點擊會關閉彈窗；沒有就留空（不允許點外部關閉）' })
    public maskNode: Node | null = null;
    @property({ type: Node, tooltip: '內容掛載點；子類別把自己的內容節點掛在這底下（純排版用，程式碼不強制要求）' })
    public contentRoot: Node = null!;
}
